    caches.open('v1').then(cache => cache.addAll(['/', '/index.html', '/app.js']))
  );
});

self.addEventListener('activate', event => {
  // clean up old cache versions here if needed
});

self.addEventListener('fetch', event => {
  event.respondWith(
    caches.match(event.request).then(resp => resp || fetch(event.request))
  );
});
```

**Caveats**

- Must be served over HTTPS (exception: `http://localhost` for dev).
- Scope defaults to the directory containing the file — `/sw.js` at root gets full-site scope; `/scripts/sw.js` only controls `/scripts/*` unless the server sends `Service-Worker-Allowed: /`.
- Updates to `sw.js` are detected on navigation, but the new worker won't take control of open pages until they're closed/reloaded (or you call `skipWaiting()`/`clients.claim()`).
- Caching logic is entirely your responsibility — a badly written `fetch` handler can serve stale content indefinitely.
